function resetTradeOffer(keepFeedback=false,targetId=null,keepSubmissionLock=false){tradeOffer={targetId,offered:new Set(),requested:new Set(),offeredPicks:new Set(),requestedPicks:new Set()};if(!keepFeedback)tradeFeedback=null;if(!keepSubmissionLock)tradeSubmissionLocked=false;}
