function deleteSave(id){const entry=allSaves().find(x=>x.id===id);if(!entry||!confirm(`Delete \"${entry.name}\"? This cannot be undone.`))return;try{writeSaves(allSaves().filter(x=>x.id!==id));if(saveId===id){saveId=null;}renderSavedLeagues();showToast("Save deleted");}catch(error){console.error("Save deletion failed",error);showToast("Could not delete that save.","error");}}
