  const lineup=impact.after.starters.map(player=>`<div class="rotation-starter ${player.incoming?"incoming":""} ${player.natural?"":"out-of-position"}"><span>${player.slot}</span>${player.playerId!==null&&player.playerId!==undefined?`<button class="player-link" data-player-id="${player.playerId}"><strong>${escapeHtml(player.name)}</strong><small>Projected starter${player.incoming?" · incoming":""}${player.natural?"":" · out of position"}</small></button>`:`<strong>Open roster spot</strong>`}</div>`).join("");
  return `<section class="roster-impact"><div class="roster-impact-heading"><div><p class="eyebrow">ROTATION OUTLOOK · YOUR STAFF'S ESTIMATE</p><h4>Estimated ${escapeHtml(target.name)} post-trade rotation</h4><small>${staffConfidence}% confidence · this measures projected basketball strength, not how close the trade is to acceptance</small></div><span class="rotation-delta ${deltaClass}">Rotation: ${deltaLabel}</span></div><div class="rotation-scoreboard"><div><small>Estimated before</small><strong>~${Math.round(impact.before.score)}</strong></div><span aria-hidden="true">→</span><div><small>Estimated after</small><strong>~${Math.round(impact.after.score)}</strong></div><div><small>Bench outlook</small><strong>${benchLabel}</strong></div></div><div class="projected-lineup">${lineup}</div></section>`;
