function capStatusText(sheet){
  if(sheet.capSpace>0)return `$${sheet.capSpace.toFixed(1)}M in cap room`;
  if(sheet.apronsActive&&sheet.secondApronRoom<0)return `$${Math.abs(sheet.secondApronRoom).toFixed(1)}M above the second apron`;
  if(sheet.apronsActive&&sheet.firstApronRoom<0)return `$${Math.abs(sheet.firstApronRoom).toFixed(1)}M above the first apron`;
  if(sheet.taxRoom<0)return `$${Math.abs(sheet.taxRoom).toFixed(1)}M into the tax`;
  return `$${sheet.overCap.toFixed(1)}M over the cap`;
}

function tradeCapSummaryHtml(viewer,target,match=null){
  const sheets=[teamCapSheet(league,viewer.id),teamCapSheet(league,target.id)],rules=sheets[0],preset=financialRulePreset(league),thresholds=preset.apronsActive?`$${rules.salaryCap.toFixed(3)}M cap · $${rules.luxuryTax.toFixed(3)}M tax · $${rules.firstApron.toFixed(3)}M / $${rules.secondApron.toFixed(3)}M aprons`:`$${rules.salaryCap.toFixed(3)}M soft cap · $${rules.luxuryTax.toFixed(3)}M luxury-tax line · no aprons`;
  const live=match?`<div class="live-salary-check ${match.valid?"legal":"illegal"}"><strong>${match.valid?"✓ Current player salaries match":"Salary mismatch in current construction"}</strong><span>${match.valid?"The selected player contracts fit both teams' trade limits.":escapeHtml(match.reasons.join(" "))}</span></div>`:"";
  return `<div class="cap-summary-heading"><div><p class="eyebrow">${seasonName(league.seasonYear)} CAP SHEETS · ${escapeHtml(preset.shortName.toUpperCase())}</p><strong>${thresholds}</strong></div><span class="tag">${preset.apronsActive?"APRON MATCHING ACTIVE":"SIMPLIFIED 125% MATCHING"}</span></div><div class="cap-summary-teams">${sheets.map((sheet,index)=>`<section><small>${escapeHtml(index?target.name:viewer.name)} payroll</small><strong>$${sheet.payroll.toFixed(3)}M</strong><span>${escapeHtml(sheet.status)} · ${escapeHtml(capStatusText(sheet))}</span></section>`).join("")}</div>${live}`;
}

function financeSeasonName(year){return `${year}–${String(year+1).slice(-2)}`;}
function financeMoney(amount){return `$${Number(amount||0).toFixed(3)}M`;}
function roomFromLine(amount,line){return amount>=0?`${financeMoney(amount)} below ${line}`:`${financeMoney(Math.abs(amount))} above ${line}`;}
function financeOperatingRead(sheet){
  if(!sheet.apronsActive&&sheet.status==="Luxury tax")return "Simplified rules: the team is above the luxury-tax line, but there are no apron restrictions. Over-cap trades use universal 125% salary matching.";
  if(!sheet.apronsActive&&sheet.status==="Over the cap")return "Simplified rules: the team has no ordinary cap room, but there are no aprons. Trades, Bird rights, minimum contracts and future cap exceptions remain available.";
  if(!sheet.apronsActive)return "Simplified rules: the team can operate with cap room, and neither the first nor second apron exists in this league.";
  if(sheet.status==="Above second apron")return "Second-apron restrictions are active. The team cannot aggregate multiple salaries in a trade and will have very limited exception flexibility.";
  if(sheet.status==="Above first apron")return "First-apron restrictions are active. Trades require 100% salary matching and certain spending tools can hard-cap the team.";
  if(sheet.status==="Luxury tax")return "The team is paying tax but remains below the first apron. Bird rights, trades and permitted exceptions are its primary paths to add talent.";
  if(sheet.status==="Over the cap")return "The team has no ordinary cap room. Bird rights, trades, minimum contracts and cap exceptions are its primary paths to add talent.";
  return "The team can operate with cap room. Using certain exceptions later can change its operating status and create a hard cap.";
}
function financeSalaryCell(player,seasonYear){
  const row=player.contract?.salaries?.find(salary=>salary.seasonYear===seasonYear);if(!row)return '<span class="finance-no-salary">—</span>';
  const detail=row.option&&!row.option.includes("exercised")?row.option:row.guaranteed?(row.option||"Guaranteed"):"Non-guaranteed";
  return `<strong>${financeMoney(row.amount)}</strong><small>${escapeHtml(detail)}</small>`;
}
function financeDecisionItem(player,label,detail){return `<div class="finance-decision"><button class="player-link" data-player-id="${player.id}"><strong>${escapeHtml(player.name)}</strong><small>${escapeHtml(label)}</small></button><span>${escapeHtml(detail)}</span></div>`;}
function financeGuideSection(id,title,short,body){return `<section class="finance-guide-section" data-guide-section="${id}"><div><h3>${title}</h3><span>${short}</span></div><p>${body}</p></section>`;}
