function salaryMatchHtml(match){
  if(!match?.checks)return "";
  const preset=financialRulePreset(league);return `<section class="salary-match ${match.valid?"legal":"illegal"}"><div class="salary-match-heading"><div><p class="eyebrow">${preset.apronsActive?"MODERN NBA":"SIMPLIFIED"} SALARY MATCH</p><h4>${match.valid?"Legal salary construction":"Salary construction must change"}</h4></div><span class="tag">${match.valid?"LEGAL":"MISMATCH"}</span></div><div>${match.checks.map(check=>`<section><small>${escapeHtml(league.teams[check.teamId]?.name||"Team")} · ${escapeHtml(check.status)}</small><strong>$${check.outgoing.toFixed(1)}M out → $${check.incoming.toFixed(1)}M in</strong><span>${escapeHtml(check.reason)} Post-trade payroll: $${check.postPayroll.toFixed(1)}M.</span></section>`).join("")}</div></section>`;
}

function completedTradeAssetsHtml(playerIds=[],pickIds=[]){
  const players=playerIds.map(id=>league.players.find(p=>p.id===id)).filter(Boolean).map(p=>{const currentTeam=league.teams[p.teamId];return `<div class="completed-trade-asset"><button class="player-link" data-player-id="${p.id}"><strong>${escapeHtml(p.name)}</strong><small>${p.position}/${p.secondary} · now ${escapeHtml(currentTeam?.name||"Unsigned")}</small></button><b>$${p.contract?.salary||0}M</b></div>`;});
  const picks=pickIds.map(id=>league.draftPicks.find(p=>p.id===id)).filter(Boolean).map(p=>{const original=league.teams[p.originalTeamId],owner=league.teams[p.teamId],round=p.round===1?"1st":"2nd";return `<div class="completed-trade-asset completed-pick"><span><strong>${p.year} ${round} · ${escapeHtml(p.protection||"Unprotected")}</strong><small>Originally ${escapeHtml(original?.name||"Unknown")} · now ${escapeHtml(owner?.name||"Unknown")}</small></span></div>`;});
  return [...players,...picks].join("")||'<span class="trade-empty">No assets recorded</span>';
}

