function marketRead(row){const move=(row.preseasonRank||row.rank)-row.rank;if(row.preseasonRank<=6&&row.rank>=15)return "Disappointing contender — monitor as seller";if(row.team.declaredDirection==="Rebuilding")return "Likely seller; seek veterans or absorb salary";if(row.team.declaredDirection==="Contending")return "Likely buyer; core players difficult to acquire";if(move>=6)return "Rising team; may seek a finishing piece";if(move<=-6)return "Falling below expectations; direction may change";return "Market position currently stable";}

function teamFitScore(player,report,viewerId){
  const roster=league.players.filter(p=>p.teamId===viewerId),positionStrength=Object.fromEntries(["PG","SG","SF","PF","C"].map(pos=>[pos,Math.max(0,...roster.filter(p=>p.position===pos).map(p=>scoutingReport(league,viewerId,p).perceived))])),weakest=Math.min(...Object.values(positionStrength)),needBonus=positionStrength[player.position]===weakest?10:positionStrength[player.position]<=weakest+4?5:0;return report.perceived+needBonus+(report.perceivedPotential-report.perceived)*.25;
}

function sortScoutingRows(rows,sort,viewerId){return [...rows].sort((a,b)=>sort==="fit"?teamFitScore(b.p,b.r,viewerId)-teamFitScore(a.p,a.r,viewerId):sort==="position"?a.p.position.localeCompare(b.p.position)||b.r.perceived-a.r.perceived:b.r.perceived-a.r.perceived);}

function projectedDraftSlot(teamId){const inverse=[...league.teams].sort((a,b)=>a.wins/(a.wins+a.losses||1)-b.wins/(b.wins+b.losses||1)||(a.pointsFor-a.pointsAgainst)/(a.wins+a.losses||1)-(b.pointsFor-b.pointsAgainst)/(b.wins+b.losses||1));return inverse.findIndex(t=>t.id===teamId)+1;}

function autoAssignDraft(viewerId){
  const viewer=league.teams[viewerId],strategy=$("draft-auto-strategy").value,rows=league.prospects.map(p=>({p,r:scoutingReport(league,viewerId,p)})).sort((a,b)=>b.r.marketScore-a.r.marketScore),slot=projectedDraftSlot(viewerId),capacity=scoutingDepartment(league,viewerId).collegeCapacity;for(const p of league.prospects)setScoutingTarget(league,viewerId,p.id,false);let pool;if(strategy==="range")pool=rows.slice(Math.max(0,slot-6),Math.min(rows.length,slot+6));else if(strategy==="position")pool=sortScoutingRows(rows,"fit",viewerId);else pool=rows;const choices=pool.slice(0,capacity);for(const x of choices)setScoutingTarget(league,viewerId,x.p.id,true);draftBoardMode="assigned";render();saveLeague();showToast(`✓ Scouts assigned to ${choices.length} prospects`);
}

function hasDraftAssignments(viewerId){const targets=league.teams[viewerId].scoutingTargets||{};return league.prospects.some(p=>targets[p.id]!==undefined);}
function maybePromptScouting(){if(controlledTeamId===null||league.scoutingReminderHandled||league.day<10||hasDraftAssignments(controlledTeamId)||!$("setup-screen").classList.contains("closed"))return;league.scoutingReminderHandled=true;$("scouting-reminder").showModal();saveLeague();}
function simulateFromUi(count){simulateDays(league,count);render();saveLeague();maybePromptScouting();}

function rankingExplanation(row,viewerId){
  const snapshotDay=row.snapshotDay||0,games=league.results.filter(g=>g.day<=snapshotDay&&g.day>snapshotDay-7&&(g.homeId===row.team.id||g.awayId===row.team.id)),wins=games.filter(g=>(g.homeId===row.team.id&&g.homeScore>g.awayScore)||(g.awayId===row.team.id&&g.awayScore>g.homeScore)).length,losses=games.length-wins;
  if(!games.length)return `Preseason rank #${row.preseasonRank} is based on roster talent, depth and projected fit.`;
  const margins=games.map(g=>g.homeId===row.team.id?g.homeScore-g.awayScore:g.awayScore-g.homeScore),margin=(margins.reduce((a,b)=>a+b,0)/margins.length).toFixed(1),roster=league.players.filter(p=>p.teamId===row.team.id&&p.season.performances.length).map(p=>{const recent=p.season.performances.slice(Math.max(0,snapshotDay-7),snapshotDay);return {p,form:recent.reduce((a,b)=>a+b,0)/Math.max(1,recent.length),r:scoutingReport(league,viewerId,p)};}).sort((a,b)=>(b.form-b.r.perceived)-(a.form-a.r.perceived)),hot=roster[0],cold=roster.at(-1),move=(row.preseasonRank||row.rank)-row.rank;
  let reason=`Went ${wins}-${losses} over the latest ranking period with an average margin of ${Number(margin)>=0?"+":""}${margin}. `;
  if(losses>=5&&row.preseasonRank>20)reason+="The roster has performed like a rebuilding team and currently lacks enough high-end production. ";
  else if(losses>=4)reason+=cold&&cold.form<cold.r.perceived-3?`${cold.p.name} struggled while the team played below its expected level. `:"Several losses came from the roster collectively underperforming expectations. ";
  else if(wins>=5)reason+=hot&&hot.form>hot.r.perceived+3?`${hot.p.name}'s strong week helped drive the rise. `:"Strong team-wide execution drove the week. ";
  if(move>=5)reason+=`That pushed them ${move} spots above their preseason projection.`;else if(move<=-5)reason+=`They remain ${Math.abs(move)} spots below their preseason projection.`;else reason+="Their position remains reasonably close to preseason expectations.";
  reason+=` Season overview: ${row.team.wins}-${row.team.losses}, ${(row.net>=0?"+":"")+row.net.toFixed(1)} net rating, currently assessed as ${row.team.declaredDirection.toLowerCase()}.`;
  return reason;
}

function renderScouting(viewerId){
  $("scouting-draft-label").textContent=`${league.seasonYear+1} DRAFT CLASS`;
  const standingsPool=standingsConference==="All"?league.teams:league.teams.filter(t=>t.conference===standingsConference);
  const standings=[...standingsPool].sort((a,b)=>{const ag=a.wins+a.losses,bg=b.wins+b.losses,ap=ag?a.wins/ag:.5,bp=bg?b.wins/bg:.5,anet=ag?(a.pointsFor-a.pointsAgainst)/ag:0,bnet=bg?(b.pointsFor-b.pointsAgainst)/bg:0;return bp-ap||bnet-anet||b.wins-a.wins;});
  $("standings-body").innerHTML=standings.map((t,i)=>{const games=t.wins+t.losses,net=games?(t.pointsFor-t.pointsAgainst)/games:0,pct=games?(t.wins/games).toFixed(3).replace(/^0/,""):"—",ours=t.id===viewerId;return `<tr class="${ours?"controlled-team-row":""}"><td><strong>#${i+1}</strong></td><td>${t.name}${ours?'<span class="controlled-star" title="Your organization">★</span>':""}</td><td>${t.conference}</td><td>${t.wins}-${t.losses}</td><td>${pct}</td><td>${games?(net>=0?"+":"")+net.toFixed(1):"—"}</td><td>${t.declaredDirection}</td></tr>`;}).join("");
  const rankings=powerRankings(league,viewerId,rankingConference,false);
  const snapshotDay=rankings[0]?.snapshotDay||0;$("ranking-update-note").textContent=snapshotDay?`Official week ${Math.ceil(snapshotDay/7)} snapshot · records and net ratings are current`:`Preseason snapshot · first update after game date 7`;
  $("power-rankings-body").innerHTML=rankings.map(r=>{const move=r.preseasonRank?r.preseasonRank-r.rank:0,arrow=move>0?`▲${move}`:move<0?`▼${Math.abs(move)}`:"—",games=r.team.wins+r.team.losses,ours=r.team.id===viewerId;return `<tr class="${ours?"controlled-team-row":""}"><td><strong>#${r.rank}</strong> <small class="${move>0?"up":move<0?"down":""}">${arrow}</small></td><td>#${r.preseasonRank||"—"}</td><td>${r.team.name}${ours?'<span class="controlled-star" title="Your organization">★</span>':""}</td><td>${r.team.conference}</td><td>${r.team.wins}-${r.team.losses}</td><td>${games?(r.net>=0?"+":"")+r.net.toFixed(1):"—"}</td><td>${r.team.declaredDirection}</td><td>${rankingExplanation(r,viewerId)}</td></tr>`;}).join("");
  const department=scoutingDepartment(league,viewerId),activeProAssignments=Object.keys(league.teams[viewerId].scoutingTargets||{}).map(Number).filter(id=>league.players.some(player=>player.id===id)).length,teamId=Number($("scout-team-select").value),proPosition=$("pro-position").value,proSort=$("pro-sort").value,allProRows=sortScoutingRows(rosterRows(teamId,viewerId).filter(x=>proPosition==="All"||x.p.position===proPosition),proSort,viewerId),assignedProRows=allProRows.filter(x=>x.r.targeted),proRows=proBoardMode==="assigned"?assignedProRows:allProRows;
  $("assigned-pro-count").textContent=`${activeProAssignments} / ${department.proCapacity}`;document.querySelectorAll(".pro-view-tab").forEach(x=>x.classList.toggle("active",x.dataset.proView===proBoardMode));$("pro-scouting-body").innerHTML=proRows.length?proRows.map(({p,r})=>`<tr><td><button class="player-link" data-player-id="${p.id}"><strong>${p.name}</strong><small>${r.marketTier}</small></button><button class="scout-target inline-target" data-player-id="${p.id}" data-targeted="${r.targeted}">${r.targeted?"Stop scouting":"Target player"}</button></td><td>${p.position}/${p.secondary}</td><td>${p.age}</td><td>${r.overallLow}–${r.overallHigh}</td><td>${scoutingKnowledgeText(r)}</td></tr>`).join(""):`<tr><td colspan="5" class="empty-state">No players on this roster are currently assigned.</td></tr>`;
  const draftPosition=$("draft-position").value,draftSort=$("draft-sort").value,allProspects=sortScoutingRows(league.prospects.map(p=>({p,r:scoutingReport(league,viewerId,p)})).filter(x=>draftPosition==="All"||x.p.position===draftPosition),draftSort,viewerId),assigned=allProspects.filter(x=>x.r.targeted),prospects=draftBoardMode==="assigned"?assigned:allProspects,slot=projectedDraftSlot(viewerId);
  $("draft-range-note").textContent=`Current record projects near draft slot ${slot} before the lottery. Range mode targets that portion of your board; ${department.collegeSpecialty.toLowerCase()} is your college scout's specialty.`;$("assigned-prospect-count").textContent=`${assigned.length} / ${department.collegeCapacity}`;$("auto-assign-draft").textContent=assigned.length?"✓ Scouts assigned":"Assign scouts automatically";$("auto-assign-draft").classList.toggle("assigned",assigned.length>0);document.querySelectorAll("[data-draft-view]").forEach(x=>x.classList.toggle("active",x.dataset.draftView===draftBoardMode));
  $("draft-board-body").innerHTML=prospects.length?prospects.map(({p,r})=>{const c=collegeAverages(p),rank=allProspects.findIndex(x=>x.p.id===p.id)+1;return `<tr><td>#${rank}</td><td><button class="player-link" data-player-id="${p.id}"><strong>${p.name}</strong><small>${p.college} · ${c.gp?`${c.ppg} PPG in ${c.gp} GP`:"No college games yet"}</small></button><button class="scout-target inline-target" data-player-id="${p.id}" data-targeted="${r.targeted}">${r.targeted?"Stop scouting":"Target prospect"}</button></td><td>${p.position}/${p.secondary}</td><td>${p.age}</td><td>${r.overallLow}–${r.overallHigh}</td><td>${r.estimates.potential.low}–${r.estimates.potential.high}</td><td>${scoutingKnowledgeText(r)}</td></tr>`;}).join(""):`<tr><td colspan="7" class="empty-state">No prospects are currently assigned. Target one manually or use automatic assignment.</td></tr>`;
}

function scoutingKnowledgeText(report){return `${report.confidence}%${report.targeted?` · ${report.targetDays} days targeted`:report.retainedKnowledge?` · ${report.targetDays} days retained`:""}`;}

