function offseasonTransactionHtml(transaction){
  const team=league.teams[transaction.teamId],offerTeam=league.teams[transaction.offerTeamId];return `<div class="offseason-transaction"><button class="player-link" data-player-id="${transaction.playerId}"><strong>${escapeHtml(transaction.playerName)}</strong><small>${escapeHtml(team?.name||"Unknown team")} · ${transaction.years} year${transaction.years===1?"":"s"} · ${contractMoney(transaction.salary)} annually</small></button><span>${transaction.matched?`Matched ${escapeHtml(offerTeam?.name||"offer sheet")}`:escapeHtml(transaction.mechanism)}</span></div>`;
}

function leagueFreeAgencyBreakdownHtml(viewerId,open=false){
  const transactions=league.offseason?.transactions||[],teams=[...league.teams].sort((a,b)=>a.id===viewerId?-1:b.id===viewerId?1:a.name.localeCompare(b.name)),signingTeams=new Set(transactions.map(transaction=>transaction.teamId)).size;
  const rows=teams.map(team=>{
    const signings=transactions.filter(transaction=>transaction.teamId===team.id),salary=signings.reduce((sum,transaction)=>sum+Number(transaction.salary||0),0),rosterSize=league.players.filter(player=>player.teamId===team.id).length;
    const players=signings.length?signings.map(transaction=>{const player=league.players.find(item=>item.id===transaction.playerId),report=player?scoutingReport(league,viewerId,player):null,talent=report?`${report.overallLow}–${report.overallHigh} OVR · `:"";return `<div class="team-free-agent-signing"><button class="player-link" data-player-id="${transaction.playerId}"><strong>${escapeHtml(transaction.playerName)}</strong><small>${talent}${transaction.years} yr · ${contractMoney(transaction.salary)} annually</small></button><span>${escapeHtml(transaction.matched?"Matched offer sheet":transaction.mechanism)}</span></div>`;}).join(""):'<span class="no-team-signings">No signings</span>';
    return `<tr class="${team.id===viewerId?"controlled-team-row":""}"><td><strong>${escapeHtml(team.name)}</strong><small>${team.id===viewerId?"Your organization":team.conference}</small></td><td><strong>${signings.length}</strong></td><td>${players}</td><td><strong>${contractMoney(salary)}</strong><small>first-year salary added</small></td><td>${rosterSize} / 18</td></tr>`;
  }).join("");
  return `<details class="league-free-agency-breakdown" ${open?"open":""}><summary><div><p class="eyebrow">LEAGUE-WIDE ACTIVITY</p><h3>Free agency by team</h3><small>Every organization is listed with its additions, contract terms and first-year salary committed.</small></div><span>${transactions.length} signing${transactions.length===1?"":"s"} · ${signingTeams} team${signingTeams===1?"":"s"} made signings</span></summary><div class="table-wrap league-free-agency-table"><table><thead><tr><th>Organization</th><th>Signings</th><th>Players added</th><th>First-year money</th><th>Roster</th></tr></thead><tbody>${rows}</tbody></table></div></details>`;
}

function appendLeagueFreeAgencyBreakdown(viewerId){
  const offseason=league.offseason;if(!offseason||!["Free Agency","Ready for Next Season"].includes(offseason.stage))return;
  const target=offseason.stage==="Free Agency"?document.querySelector(".free-agent-market"):document.querySelector(".ready-grid");
  if(!target||document.querySelector(".league-free-agency-breakdown"))return;
  if(offseason.stage==="Free Agency"){
    const unsignedCount=league.players.filter(player=>player.teamId===null&&player.freeAgency?.status==="Available").length;
    target.insertAdjacentHTML("beforebegin",`<nav class="free-agency-subnav" aria-label="Free agency views"><button class="free-agency-subtab ${freeAgencyView==="unsigned"?"active":""}" data-free-agency-view="unsigned">Unsigned players <span>${unsignedCount}</span></button><button class="free-agency-subtab ${freeAgencyView==="signings"?"active":""}" data-free-agency-view="signings">Team signings <span>${offseason.transactions.length}</span></button></nav>`);
    target.insertAdjacentHTML("afterend",leagueFreeAgencyBreakdownHtml(viewerId,true));
    target.classList.toggle("hidden",freeAgencyView!=="unsigned");document.querySelector(".league-free-agency-breakdown")?.classList.toggle("hidden",freeAgencyView!=="signings");
    return;
  }
  target.insertAdjacentHTML("afterend",leagueFreeAgencyBreakdownHtml(viewerId,true));
}

function financeHelpButton(label,focus){return `<button class="finance-term-link finance-help" data-finance-focus="${focus}">${label}<span aria-hidden="true">?</span></button>`;}
function selectedFilter(value,current){return String(value)===String(current)?"selected":"";}
function sortFreeAgentRows(rows,sort){
  const [field,direction]=String(sort||"fit-desc").split("-"),sign=direction==="asc"?1:-1,value=(row,key)=>key==="fit"?row.fit.score:key==="overall"?row.report.perceived:key==="interest"?row.interest.score:key==="salary"?row.market.salary:key==="age"?row.player.age:row.player.name.toLowerCase();
  return rows.sort((a,b)=>{const left=value(a,field),right=value(b,field),comparison=typeof left==="string"?left.localeCompare(right):left-right;return comparison*sign||b.report.perceived-a.report.perceived||a.player.id-b.player.id;});
}
function freeAgentFilterControls(total,visible){
  const options=(values,current)=>values.map(([value,label])=>`<option value="${value}" ${selectedFilter(value,current)}>${label}</option>`).join("");
  return `<div class="free-agent-filters"><div class="free-agent-filter-heading"><div><strong>Search, filter & order</strong><small>Overall and team grade use your staff's current estimates.</small></div><span>${visible} of ${total} shown</span></div><div class="free-agent-filter-grid"><label>Player name<input id="fa-filter-name" type="search" placeholder="Search free agents" value="${escapeHtml(freeAgentFilters.query)}"></label><label>Position<select id="fa-filter-position">${options([["All","All positions"],["PG","Point guard"],["SG","Shooting guard"],["SF","Small forward"],["PF","Power forward"],["C","Center"]],freeAgentFilters.position)}</select></label><label>Affordability<select id="fa-filter-affordability">${options([["all","All players"],["affordable","Affordable for us"],["rights","Our Bird rights"],["cap","Fits cap room"],["mle","Fits mid-level"],["minimum","Fits minimum"],["out","Out of range"]],freeAgentFilters.affordability)}</select></label><label>Order by<select id="fa-filter-sort">${options([["fit-desc","Team grade: highest to lowest"],["fit-asc","Team grade: lowest to highest"],["overall-desc","Overall: highest to lowest"],["overall-asc","Overall: lowest to highest"],["interest-desc","Interest: highest to lowest"],["interest-asc","Interest: lowest to highest"],["salary-asc","Salary: lowest to highest"],["salary-desc","Salary: highest to lowest"],["age-asc","Age: lowest to highest"],["age-desc","Age: highest to lowest"]],freeAgentFilters.sort)}</select></label></div><div class="free-agent-filter-actions"><button id="fa-reset-filters" class="ghost">Reset</button><button id="fa-apply-filters">Apply</button></div></div>`;
}
function interestMeter(interest){return `<div class="interest-read"><div class="interest-label"><strong>${escapeHtml(interest.label)}</strong><span>${interest.score}/100</span></div><div class="interest-meter" role="meter" aria-label="${escapeHtml(interest.label)} interest" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${interest.score}"><span style="width:${interest.score}%"></span></div><small>${interest.drivers.length?escapeHtml(interest.drivers.join(" · ")):"No strong preference yet"}</small></div>`;}

function unsignedPlayerFilterControls(total,visible){
  const options=(values,current)=>values.map(([value,label])=>`<option value="${value}" ${selectedFilter(value,current)}>${label}</option>`).join("");
  return `<div class="unsigned-player-filters"><div class="free-agent-filter-heading"><div><strong>Search & order unsigned players</strong><small>Talent and team grade use your staff's current estimates.</small></div><span>${visible} of ${total} shown</span></div><div class="unsigned-filter-grid"><label>Player name<input id="unsigned-filter-name" type="search" placeholder="Search players" value="${escapeHtml(unsignedPlayerFilters.query)}"></label><label>Position<select id="unsigned-filter-position">${options([["All","All positions"],["PG","Point guard"],["SG","Shooting guard"],["SF","Small forward"],["PF","Power forward"],["C","Center"]],unsignedPlayerFilters.position)}</select></label><label>Order by<select id="unsigned-filter-sort">${options([["fit-desc","Team grade: highest to lowest"],["fit-asc","Team grade: lowest to highest"],["overall-desc","Overall: highest to lowest"],["overall-asc","Overall: lowest to highest"],["interest-desc","Interest: highest to lowest"],["interest-asc","Interest: lowest to highest"],["salary-asc","Salary: lowest to highest"],["salary-desc","Salary: highest to lowest"],["age-asc","Age: lowest to highest"],["age-desc","Age: highest to lowest"]],unsignedPlayerFilters.sort)}</select></label></div><div class="free-agent-filter-actions"><button id="unsigned-reset-filters" class="ghost">Reset</button><button id="unsigned-apply-filters">Apply</button></div></div>`;
}

function renderUnsignedPlayers(viewerId){
  const body=$("unsigned-players-body"),team=league.teams[viewerId],all=league.players.filter(player=>player.teamId===null&&player.freeAgency?.status!=="Signed").map(player=>({player,report:scoutingReport(league,viewerId,player),market:freeAgentMarketValue(league,player.id),fit:freeAgentTeamFit(league,viewerId,player.id),interest:freeAgentInterest(league,viewerId,player.id)}));
  const visible=all.filter(row=>(!unsignedPlayerFilters.query||row.player.name.toLowerCase().includes(unsignedPlayerFilters.query.toLowerCase()))&&(unsignedPlayerFilters.position==="All"||row.player.position===unsignedPlayerFilters.position||row.player.secondary===unsignedPlayerFilters.position));
  sortFreeAgentRows(visible,unsignedPlayerFilters.sort);
  const rows=visible.map(({player,report,market,fit,interest})=>{const priorTeam=Number.isInteger(player.freeAgency?.priorTeamId)?league.teams[player.freeAgency.priorTeamId]:null,twoWayEligible=controlledTeamId===viewerId&&league.phase==="Regular Season"&&player.age<=25&&(player.experience||0)<=2;return `<tr><td><button class="player-link" data-player-id="${player.id}"><strong>${escapeHtml(player.name)}</strong><small>${player.position}/${player.secondary} · Age ${player.age}</small></button></td><td><strong>${report.overallLow}–${report.overallHigh}</strong><small>Peak ${report.estimates.potential.low}–${report.estimates.potential.high} · ${report.confidence}% confidence</small></td><td><div class="team-fit-read"><span class="team-fit-grade grade-${fit.grade[0].toLowerCase()}">${fit.grade}</span><div><strong>${escapeHtml(fit.label)}</strong><small>${escapeHtml(fit.reasons.join(" · "))}</small></div></div></td><td>${interestMeter(interest)}</td><td><strong>${contractMoney(market.salary)}</strong><small>${market.years} year target</small></td><td><strong>${escapeHtml(priorTeam?.name||"League free agent")}</strong><small>${player.freeAgency?.restricted?"Restricted":"Unrestricted"} free agent</small></td><td>${twoWayEligible?`<button class="sign-two-way" data-player-id="${player.id}">Sign two-way</button><small>$0.600M · one season · up to 3 slots</small>`:'<span class="contract-action-note">Standard contract only</span>'}</td></tr>`;}).join("");
  $("unsigned-team-name").textContent=`Currently unsigned · ${team.name} view`;$("unsigned-player-count").textContent=`${all.length} AVAILABLE`;
  const phaseNote=league.offseason?.stage==="Free Agency"?'Offers are handled from the Unsigned Players view inside the Free Agency tab.':'This screen remains available during the regular season as a league-wide reference.';
  body.innerHTML=`${unsignedPlayerFilterControls(all.length,visible.length)}<p class="unsigned-phase-note">${phaseNote}</p><div class="table-wrap unsigned-player-table"><table><thead><tr><th>Player</th><th>Talent</th><th>Team grade</th><th>Interest</th><th>Asking price</th><th>Last team</th><th>Roster action</th></tr></thead><tbody>${rows||'<tr><td colspan="7" class="empty-state">No unsigned players match these filters.</td></tr>'}</tbody></table></div>`;
}

function renderOffseason(viewerId){
  const body=$("offseason-body"),offseason=league.offseason,year=offseason?.year||(league.seasonYear||2026)+1,team=league.teams[viewerId],canManage=controlledTeamId!==null&&viewerId===controlledTeamId;$("offseason-title").textContent=`${year} offseason · ${team.name}`;
  if(!offseason){$("offseason-stage-tag").textContent="NOT STARTED";body.innerHTML=league.draft?.status==="Complete"?`<section class="offseason-launch"><p class="eyebrow">DRAFT COMPLETE</p><h3>Move into contract decisions</h3><p>Team and player options come first. Expiring contracts then become free agents with cap holds and re-signing rights attached.</p><button id="start-offseason">Begin post-draft offseason</button></section>`:'<p class="empty-state">Complete the draft before opening the rest of the offseason.</p>';return;}
  $("offseason-stage-tag").textContent=offseason.stage.toUpperCase();
  if(offseason.stage==="Contract Decisions"){
    const decisions=offseason.decisions.filter(decision=>decision.teamId===viewerId),rows=decisions.map(decision=>{const player=league.players.find(item=>item.id===decision.playerId),pending=decision.status==="Pending"&&canManage;return `<article class="option-card"><div><button class="player-link" data-player-id="${player.id}"><strong>${escapeHtml(player.name)}</strong><small>${player.position}/${player.secondary} · ${decision.kind} · ${contractMoney(decision.amount)}</small></button><span class="option-status ${decision.status.toLowerCase()}">${escapeHtml(decision.status)}</span></div>${pending?`<label>Decision<select class="option-decision" data-player-id="${player.id}"><option value="exercise" ${decision.recommendation==="Exercise"?"selected":""}>Exercise option</option><option value="decline" ${decision.recommendation==="Decline"?"selected":""}>Decline option</option></select></label><small>Staff recommendation: ${decision.recommendation}</small>`:`<p>${decision.kind==="Player option"?"The player's camp made this decision.":canManage?"This decision is final.":"AI front office decision."}</p>`}</article>`;}).join("");
    body.innerHTML=`<section class="offseason-summary"><div><p class="eyebrow">STEP 1 OF 3</p><h3>Contract decisions</h3><p>Exercised options stay on the cap. Declined options and expiring contracts enter free agency.</p></div><span>${decisions.filter(decision=>decision.status==="Pending").length} pending for ${escapeHtml(team.name)}</span></section><div class="option-grid">${rows||'<p class="empty-state">This organization has no option decisions. Expiring contracts will still enter free agency.</p>'}</div><div class="offseason-actions"><button id="finalize-options">${canManage?"Finalize decisions & open free agency":"Resolve league decisions"}</button></div>`;return;
  }
  if(offseason.stage==="Free Agency"){
    const sheet=freeAgencyTeamSheet(league,viewerId),holds=(offseason.capHolds||[]).filter(hold=>hold.teamId===viewerId&&hold.active),transactions=offseason.transactions.slice(-12).reverse(),pendingOffers=offseason.pendingOffers||[],viewerOffers=pendingOffers.filter(offer=>offer.teamId===viewerId),allAvailable=league.players.filter(player=>player.freeAgency?.status==="Available").map(player=>({player,report:scoutingReport(league,viewerId,player),market:freeAgentMarketValue(league,player.id),fit:freeAgentTeamFit(league,viewerId,player.id),interest:freeAgentInterest(league,viewerId,player.id),affordability:freeAgentAffordability(league,viewerId,player.id)}));
    const affordabilityMatch=row=>freeAgentFilters.affordability==="all"||freeAgentFilters.affordability==="affordable"&&row.affordability.affordable||freeAgentFilters.affordability==="rights"&&row.affordability.label.includes("Rights")||freeAgentFilters.affordability==="cap"&&row.affordability.mechanism==="Cap Space"||freeAgentFilters.affordability==="mle"&&row.affordability.mechanism==="Mid-Level Exception"||freeAgentFilters.affordability==="minimum"&&row.affordability.mechanism==="Minimum Salary Exception"||freeAgentFilters.affordability==="out"&&!row.affordability.affordable;
    const available=allAvailable.filter(row=>(!freeAgentFilters.query||row.player.name.toLowerCase().includes(freeAgentFilters.query.toLowerCase()))&&(freeAgentFilters.position==="All"||row.player.position===freeAgentFilters.position||row.player.secondary===freeAgentFilters.position)&&affordabilityMatch(row));
    sortFreeAgentRows(available,freeAgentFilters.sort);
    const holdRows=holds.map(hold=>{const player=league.players.find(item=>item.id===hold.playerId);return `<div class="cap-hold-row"><button class="player-link" data-player-id="${player.id}"><strong>${escapeHtml(player.name)}</strong><small>${contractMoney(hold.amount)} cap hold</small></button><div class="cap-hold-actions">${financeHelpButton(escapeHtml(hold.rightsType),"bird-rights")}${canManage?`<button class="renounce-hold ghost" data-player-id="${player.id}">Renounce</button>`:""}</div></div>`;}).join("");
    const freeAgentRows=available.map(({player,report,market,fit,interest,affordability})=>{const ownRights=player.freeAgency.priorTeamId===viewerId&&holds.some(hold=>hold.playerId===player.id),affordabilityClass=affordability.affordable?"available":"unavailable",myOffer=viewerOffers.find(offer=>offer.playerId===player.id),competition=pendingOffers.filter(offer=>offer.playerId===player.id).length,offerSalary=myOffer?.salary??market.salary,offerYears=myOffer?.years??market.years,pendingRead=myOffer?`<small class="pending-offer-read">Your offer: ${contractMoney(myOffer.salary)} × ${myOffer.years} yr · ${competition} total offer${competition===1?"":"s"}</small>`:competition?`<small class="pending-offer-read">${competition} offer${competition===1?"":"s"} already pending</small>`:"";return `<tr><td><button class="player-link" data-player-id="${player.id}"><strong>${escapeHtml(player.name)}</strong><small>${player.position}/${player.secondary} · Age ${player.age}${player.freeAgency.restricted?" · Restricted FA":""}</small></button></td><td><strong>${report.overallLow}–${report.overallHigh}</strong><small>Peak ${report.estimates.potential.low}–${report.estimates.potential.high} · ${report.confidence}% confidence</small></td><td><div class="team-fit-read"><span class="team-fit-grade grade-${fit.grade[0].toLowerCase()}">${fit.grade}</span><div><strong>${escapeHtml(fit.label)}</strong><small>${escapeHtml(fit.reasons.join(" · "))}</small></div></div></td><td>${interestMeter(interest)}</td><td><strong>${contractMoney(market.salary)}</strong><small>${market.years} year target${ownRights?` · ${escapeHtml(player.freeAgency.rightsType)} rights`:""}</small><span class="affordability-badge ${affordabilityClass}">${escapeHtml(affordability.label)}</span></td><td>${canManage?`<div class="free-agent-offer"><label><span>Annual $M</span><input class="fa-salary" data-player-id="${player.id}" type="number" min="${market.minimum}" max="${market.maxSalary}" step="0.1" value="${offerSalary}"></label><label><span>Years</span><select class="fa-years" data-player-id="${player.id}">${[1,2,3,4,5].map(years=>`<option value="${years}" ${years===offerYears?"selected":""} ${years===5&&!ownRights?"disabled":""}>${years}</option>`).join("")}</select></label><button class="make-fa-offer" data-player-id="${player.id}">${myOffer?"Update offer":"Submit offer"}</button></div>${pendingRead}`:"AI controlled"}</td></tr>`;}).join("");
    const capRoomDetail=sheet.capRoom>0?`${contractMoney(sheet.capRoom)} available`:`${contractMoney(sheet.overCapBy)} above cap after holds`;
    body.innerHTML=`<section class="offseason-summary"><div><p class="eyebrow">STEP 2 OF 3 · DAY ${offseason.day} OF ${offseason.maxDays}</p><h3>Free agency</h3><p>Offers stay pending while players compare money, contract length, team interest and roster fit. Decisions arrive as the 12-day market advances.</p></div><span>${allAvailable.length} players available · ${pendingOffers.length} offers pending</span></section><div class="free-agency-dashboard"><section>${financeHelpButton(`${seasonName(year)} committed salary`,"committed-salary")}<strong>${contractMoney(sheet.committed)}</strong></section><section>${financeHelpButton("Active cap holds","cap-holds")}<strong>${contractMoney(sheet.capHolds)}</strong></section><section>${financeHelpButton("Usable cap room","cap-room")}<strong>${contractMoney(sheet.capRoom)}</strong><small>${capRoomDetail}</small></section><section>${financeHelpButton("Mid-level remaining","mid-level")}<strong>${contractMoney(sheet.midLevelRemaining)}</strong></section><section>${financeHelpButton("Roster","roster-limit")}<strong>${sheet.rosterSize} / 18</strong><small>${viewerOffers.length} pending offer${viewerOffers.length===1?"":"s"}</small></section></div><div class="offseason-columns"><section class="cap-holds-panel"><div class="section-title"><div><p class="eyebrow">RE-SIGNING RIGHTS</p><h3>Cap holds</h3></div><span>${contractMoney(teamCapHolds(league,viewerId))}</span></div><p class="cap-hold-explainer">A renounced hold reduces cap charges immediately, but usable room stays at $0 until total charges fall below the cap.</p>${holdRows||'<p class="empty-state">No active cap holds.</p>'}</section><section class="transactions-panel"><div class="section-title"><div><p class="eyebrow">LEAGUE WIRE</p><h3>Latest signings</h3></div><span>${offseason.transactions.length} total</span></div>${transactions.length?transactions.map(offseasonTransactionHtml).join(""):'<p class="empty-state">No decisions yet. Advance the market to let players compare offers.</p>'}</section></div><section class="free-agent-market"><div class="section-title"><div><p class="eyebrow">AVAILABLE PLAYERS</p><h3>Free-agent market</h3></div><span class="roster-note">Players collect competing offers and decide over 12 days</span></div>${freeAgentFilterControls(allAvailable.length,available.length)}<div class="table-wrap"><table><thead><tr><th>Player</th><th>Talent</th><th>Team grade</th><th>Interest</th><th>Market</th><th>Offer</th></tr></thead><tbody>${freeAgentRows||'<tr><td colspan="6" class="empty-state">No free agents match these filters. Reset the board to see the full market.</td></tr>'}</tbody></table></div></section><div class="offseason-actions"><button id="sim-fa-day" class="ghost" ${offseason.day>=offseason.maxDays?"disabled":""}>Sim next free-agency day</button><button id="finish-free-agency">Complete free agency</button></div>`;return;
  }
  const roster=league.players.filter(player=>player.teamId===viewerId).sort((a,b)=>scoutingReport(league,viewerId,b).perceived-scoutingReport(league,viewerId,a).perceived),transactions=offseason.transactions.filter(transaction=>transaction.teamId===viewerId),unfinishedMarket=offseason.day<offseason.maxDays&&league.players.some(player=>player.teamId===null&&player.freeAgency?.status==="Available");
  body.innerHTML=`<section class="offseason-summary ready"><div><p class="eyebrow">STEP 3 OF 3</p><h3>Roster ready for opening night</h3><p>Every team has at least 12 players. Starting the season archives ${seasonName(league.seasonYear)}, advances contracts and generates the ${year+1} draft class.</p></div><span>${roster.length} players</span></section>${unfinishedMarket?'<section class="unfinished-market-note"><div><p class="eyebrow">OLDER SAVE DETECTED</p><h3>The remaining league market was skipped</h3><p>This offseason was completed before every AI free-agency day ran. Process the remaining market to give the rest of the league a chance to sign players before opening night.</p></div><button id="finish-free-agency">Complete remaining market</button></section>':""}<div class="ready-grid"><section><p class="eyebrow">YOUR OFFSEASON</p><h3>${transactions.length} signing${transactions.length===1?"":"s"}</h3><div>${transactions.length?transactions.map(offseasonTransactionHtml).join(""):'<p class="empty-state">No free-agent signings.</p>'}</div></section><section><p class="eyebrow">NEXT SEASON</p><h3>${seasonName(year)}</h3><p>${escapeHtml(team.name)} will open with a reset schedule, updated ages and contracts, and a new 60-player college class.</p></section></div><div class="offseason-actions"><button id="start-next-season">Start ${seasonName(year)} season</button></div>`;
}

function renderSeasonCenter(viewerId){
  const team=league.teams[viewerId],sorted=[...league.teams].sort((a,b)=>(b.wins/(b.wins+b.losses||1))-(a.wins/(a.wins+a.losses||1))||b.wins-a.wins),rank=sorted.findIndex(t=>t.id===viewerId)+1,recent=league.results.filter(g=>g.homeId===viewerId||g.awayId===viewerId).slice(-5).reverse(),playoffYear=(league.seasonYear||2026)+1;
  const offseasonStatus=league.offseason?.stage||(league.draft?.status==="Complete"?"Draft complete":league.draft?.status==="Lottery Complete"?"Draft lottery complete":league.draft?`Draft pick ${Math.min(60,(league.draft.currentPick||0)+1)} of 60`:"Draft lottery ready");
  $("season-label").textContent=league.phase==="Offseason"?`${playoffYear} OFFSEASON`:league.phase==="Postseason"?`${playoffYear} POSTSEASON`:`${seasonName(league.seasonYear)} REGULAR SEASON`;$("season-status").textContent=league.phase==="Offseason"?offseasonStatus:league.phase==="Postseason"?(league.postseason?.stage||"Play-in tournament"):league.day>=82?"Regular season complete":league.day===0?"Opening night":`Game date ${league.day} of 82`;
  $("team-record").textContent=`${team.wins}–${team.losses}`;$("record-team").textContent=team.name;$("conference-rank").textContent=league.day?`#${rank}`:"—";
  $("recent-results").innerHTML=recent.length?recent.map(g=>{const home=g.homeId===viewerId,won=(home?g.homeScore:g.awayScore)>(home?g.awayScore:g.homeScore),opp=league.teams[home?g.awayId:g.homeId];return `<b class="${won?"win":"loss"}">${won?"W":"L"}</b> ${home?g.homeScore:g.awayScore}–${home?g.awayScore:g.homeScore} vs ${opp.name}`;}).join("<br>"):"No games played";
  $("sim-day").disabled=league.phase!=="Regular Season"||league.day>=82;$("sim-ten").disabled=league.phase!=="Regular Season"||league.day>=82;updatePlayoffsTab();updateDraftTab();updateOffseasonTab();renderPostseason();
}

function seriesHtml(s){
  if(!s)return `<div class="series-card placeholder"><span>Matchup pending</span></div>`;
  const a=league.teams[s.a.teamId],b=league.teams[s.b.teamId],winner=s.winner?league.teams[s.winner.teamId]:null,seed=x=>x.seed?`#${x.seed} `:"",started=(s.aWins||0)+(s.bWins||0)>0,last=s.games?.at(-1),aScore=last?(last.homeId===a.id?last.homeScore:last.awayScore):null,bScore=last?(last.homeId===b.id?last.homeScore:last.awayScore):null;
  const boxButton=last?.gameNumber!==undefined?`<button class="playoff-box-score series-box-score ghost" data-game-number="${last.gameNumber}"><span>Box score · Game ${last.seriesGame}</span><strong>${aScore}–${bScore}</strong></button>`:"";
  return `<div class="series-card"><span>${seed(s.a)}${a.name}</span><strong>${winner||started?`${s.aWins}–${s.bWins}`:"vs"}</strong><span>${seed(s.b)}${b.name}</span>${winner?`<small>${winner.name} advances</small>`:started?"<small>Series in progress</small>":"<small>Awaiting simulation</small>"}${boxButton}</div>`;
}
function completedRound(p,stage,conference){if(p.stage===stage)return p.current?.[conference]||[];const saved=[...(p.completed||[])].reverse().find(x=>x.stage===stage);return saved?.series?.[conference]||[];}
function bracketColumn(title,series,count){const cards=[...series];while(cards.length<count)cards.push(null);return `<div class="bracket-round"><h4>${title}</h4>${cards.map(seriesHtml).join("")}</div>`;}
function conferenceBracket(p,conference){
  const seeds=p.seeds?.[conference],pendingPlayIn=seeds?[{a:seeds[6],b:seeds[7],aWins:0,bWins:0},{a:seeds[8],b:seeds[9],aWins:0,bWins:0}]:[],playInSeries=p.playIn?.[conference]?.games||completedRound(p,"Play-In",conference)||pendingPlayIn,first=completedRound(p,"First Round",conference),semis=completedRound(p,"Conference Semifinals",conference),conferenceFinal=completedRound(p,"Conference Finals",conference);
  return `<section class="conference-bracket"><h3>${conference}</h3><div class="bracket-rounds">${bracketColumn("Play-In",playInSeries,3)}${bracketColumn("First Round",first,4)}${bracketColumn("Semifinals",semis,2)}${bracketColumn("Conference Final",conferenceFinal,1)}</div></section>`;
}
function updatePlayoffsTab(){const available=league.day>=82||league.phase==="Postseason"||league.phase==="Offseason";$("playoffs-tab").classList.toggle("hidden",!available);if(!available&&activeScreen==="playoffs-screen")switchScreen("roster-screen");}
function renderPostseason(){
  const box=$("postseason-center");if(league.day<82){box.innerHTML="";return;}
  if(!league.postseason){box.innerHTML=`<div><p class="eyebrow">POSTSEASON</p><h2>Play-in tournament ready</h2><p class="subtitle">Seeds 7–10 in each conference enter the play-in. Seeds 1–6 qualified directly.</p></div><button id="advance-playoffs">Set postseason field</button>`;return;}
  const p=league.postseason,finals=completedRound(p,"Finals","Finals"),finalsBlock=finals.length?`<section class="finals-bracket"><p class="eyebrow">LEAGUE FINALS</p><h3>Championship series</h3>${finals.map(seriesHtml).join("")}</section>`:"";if(p.stage==="Season Complete"){box.innerHTML=`<div class="postseason-title"><div><p class="eyebrow">${league.seasonYear+1} CHAMPION</p><h2>${league.teams[p.champion].name}</h2><p class="subtitle">The league has entered the offseason. The completed bracket remains below.</p></div><div class="postseason-actions"><button id="go-to-draft">Open draft room</button></div></div><div class="bracket-shell">${finalsBlock}${conferenceBracket(p,"East")}${conferenceBracket(p,"West")}</div>`;return;}
  const controlledSeed=controlledTeamId===null?null:Object.values(p.seeds||{}).flat().find(x=>x.teamId===controlledTeamId),controlledInPlayIn=controlledSeed?.seed>=7&&controlledSeed?.seed<=10;
  box.innerHTML=`<div class="postseason-title"><div><p class="eyebrow">${p.stage.toUpperCase()}</p><h2>Postseason bracket</h2><p class="subtitle">${p.stage==="Play-In"&&controlledInPlayIn?`Your team is the #${controlledSeed.seed} seed. Advance the next game across every active play-in matchup, or complete the tournament.`:"Advance the next game across every active series, or finish the entire current round."}</p></div><div class="postseason-actions"><button id="simulate-playoff-game" class="ghost">Sim next game · all series</button><button id="simulate-playoff-round">Simulate current round</button></div></div><div class="bracket-shell">${finalsBlock}${conferenceBracket(p,"East")}${conferenceBracket(p,"West")}</div>`;
}

function latestTeamGame(teamId){const playoff=(league.postseason?.results||[]).filter(g=>g.homeId===teamId||g.awayId===teamId).at(-1);return playoff||league.results.filter(g=>g.homeId===teamId||g.awayId===teamId).at(-1)||null;}
function gameWinnerId(game){return game.winnerId??(game.homeScore>game.awayScore?game.homeId:game.awayId);}
function scoreBoardHtml(game){
  const winnerId=gameWinnerId(game),away=league.teams[game.awayId],home=league.teams[game.homeId];
  return `<div class="latest-scoreboard"><div class="${winnerId===away.id?"winner":""}"><span>${away.name}</span><strong>${game.awayScore}</strong>${winnerId===away.id?"<em>WINNER</em>":""}</div><span class="score-at">at</span><div class="${winnerId===home.id?"winner":""}"><span>${home.name}</span><strong>${game.homeScore}</strong>${winnerId===home.id?"<em>WINNER</em>":""}</div></div>`;
}
function gameBoxTableHtml(teamId,box,score){
  if(!box)return `<section class="box-team"><h3>${league.teams[teamId].name} <span>${score}</span></h3><p class="summary">Detailed player stats were not retained in this compact save.</p></section>`;
  return `<section class="box-team"><h3>${league.teams[teamId].name} <span>${score}</span></h3><div class="table-wrap"><table><thead><tr><th>Player</th><th>MIN</th><th>PTS</th><th>REB</th><th>AST</th><th>Game rating</th></tr></thead><tbody>${box.map(x=>{const p=league.players.find(y=>y.id===x.playerId);return `<tr><td><button class="player-link" data-player-id="${p.id}">${p.name}</button></td><td>${x.minutes}</td><td>${x.points}</td><td>${x.rebounds}</td><td>${x.assists}</td><td>${x.performance}</td></tr>`;}).join("")}</tbody></table></div></section>`;
}
function gameLabel(game){return game.postseason?`${game.stage} · Game ${game.seriesGame}`:`${gameDate(game.day-1,league.seasonYear)}`;}
function renderLatestBoxScore(viewerId){
  const panel=$("latest-box-score"),game=latestTeamGame(viewerId);panel.classList.toggle("hidden",!game);if(!game){panel.innerHTML="";return;}
  const winner=league.teams[gameWinnerId(game)];panel.innerHTML=`<div class="section-title"><div><p class="eyebrow">MOST RECENT BOX SCORE</p><h2>${gameLabel(game)}</h2></div><span class="winner-note">${winner.name} won</span></div>${scoreBoardHtml(game)}<div class="latest-box-teams">${gameBoxTableHtml(game.awayId,game.awayBox,game.awayScore)}${gameBoxTableHtml(game.homeId,game.homeBox,game.homeScore)}</div>`;
}

function renderCalendar(viewerId){
  $("calendar-team-name").textContent=league.teams[viewerId].name;$("calendar-season-label").textContent=`${seasonName(league.seasonYear)} SCHEDULE`;
  const entries=league.schedule.map((games,day)=>{
    const g=games.find(x=>x.homeId===viewerId||x.awayId===viewerId),home=g.homeId===viewerId,opp=league.teams[home?g.awayId:g.homeId],result=league.results.find(x=>x.day===day+1&&(x.homeId===viewerId||x.awayId===viewerId));
    const date=new Date(Date.UTC(league.seasonYear,9,20+day*2));let status="Upcoming";if(result){const our=home?result.homeScore:result.awayScore,their=home?result.awayScore:result.homeScore;status=`${our>their?"W":"L"} ${our}–${their}`;}return {day,date,home,opp,result,status};
  });
  const months=new Map();for(const e of entries){const key=`${e.date.getUTCFullYear()}-${e.date.getUTCMonth()}`;if(!months.has(key))months.set(key,[]);months.get(key).push(e);}
  $("calendar-body").innerHTML=[...months.values()].map(monthGames=>{const first=monthGames[0].date,year=first.getUTCFullYear(),month=first.getUTCMonth(),days=new Date(Date.UTC(year,month+1,0)).getUTCDate(),byDate=new Map(monthGames.map(e=>[e.date.getUTCDate(),e]));let cells="";for(let i=0;i<new Date(Date.UTC(year,month,1)).getUTCDay();i++)cells+='<div class="calendar-day empty"></div>';for(let d=1;d<=days;d++){const e=byDate.get(d);if(!e){cells+=`<div class="calendar-day"><span class="calendar-date">${d}</span></div>`;continue;}const action=e.result?`<button class="box-score" data-day="${e.day+1}">Box score</button>`:e.day>=league.day?`<button class="sim-to-game" data-day="${e.day+1}">Sim to</button>`:"";cells+=`<div class="calendar-day has-game ${e.day===league.day?"next-game":""}"><span class="calendar-date">${d}</span><strong>${e.home?"vs":"@"} ${e.opp.name}</strong><span class="calendar-result">${e.status}</span>${action}</div>`;}return `<section class="calendar-month"><h3>${first.toLocaleDateString("en-US",{month:"long",year:"numeric",timeZone:"UTC"})}</h3><div class="calendar-grid"><span class="weekday">Sun</span><span class="weekday">Mon</span><span class="weekday">Tue</span><span class="weekday">Wed</span><span class="weekday">Thu</span><span class="weekday">Fri</span><span class="weekday">Sat</span>${cells}</div></section>`;}).join("");
}

function openBoxScore(day,viewerId){
  const g=league.results.find(x=>x.day===day&&(x.homeId===viewerId||x.awayId===viewerId));
  if(!g)return;
  setDialogBack(null);
  $("dialog-content").innerHTML=`<p class="eyebrow">FINAL · ${gameDate(day-1,league.seasonYear)}</p>${scoreBoardHtml(g)}<div class="latest-box-teams">${gameBoxTableHtml(g.awayId,g.awayBox,g.awayScore)}${gameBoxTableHtml(g.homeId,g.homeBox,g.homeScore)}</div>`;
  $("dialog-content").querySelectorAll(".player-link").forEach(b=>b.addEventListener("click",()=>openPlayer(Number(b.dataset.playerId),viewerId,()=>openBoxScore(day,viewerId))));
  if(!$("player-dialog").open)$("player-dialog").showModal();
}

function openPostseasonBoxScore(gameNumber,viewerId){
  const game=(league.postseason?.results||[]).find(x=>x.gameNumber===gameNumber);if(!game)return;
  const winner=league.teams[gameWinnerId(game)];
  setDialogBack(null);
  $("dialog-content").innerHTML=`<div class="section-title"><div><p class="eyebrow">PLAYOFF BOX SCORE</p><h2>${gameLabel(game)}</h2></div><span class="winner-note">${winner.name} won</span></div>${scoreBoardHtml(game)}<div class="latest-box-teams">${gameBoxTableHtml(game.awayId,game.awayBox,game.awayScore)}${gameBoxTableHtml(game.homeId,game.homeBox,game.homeScore)}</div>`;
  $("dialog-content").querySelectorAll(".player-link").forEach(b=>b.addEventListener("click",()=>openPlayer(Number(b.dataset.playerId),viewerId,()=>openPostseasonBoxScore(gameNumber,viewerId))));
  if(!$("player-dialog").open)$("player-dialog").showModal();
}

function setDialogBack(action){
  dialogBackAction=action;
  $("dialog-back").classList.toggle("hidden",!action);
}

function closePlayerDialog(){setDialogBack(null);$("player-dialog").close();}

function historyHtml(player){
  const prospect=league.prospects.some(item=>item.id===player.id);if(prospect){const c=collegeAverages(player),row=c.gp?`<tr class="current-season"><td>${seasonName(league.seasonYear).replace("–","-")}</td><td>College · Current · ${player.college}</td><td>${player.age}</td><td>${c.gp}</td><td>${c.mpg}</td><td>${c.ppg}</td><td>${c.rpg}</td><td>${c.apg}</td><td>${c.fg}</td><td>${c.three}</td></tr>`:`<tr><td colspan="10">The current college season has not begun; no production has been recorded.</td></tr>`;return `<div class="history"><p class="eyebrow">BASKETBALL HISTORY</p><div class="table-wrap"><table><thead><tr><th>Season</th><th>Level</th><th>Age</th><th>GP</th><th>MIN</th><th>PTS</th><th>REB</th><th>AST</th><th>FG%</th><th>3P%</th></tr></thead><tbody>${row}</tbody></table></div></div>`;}
  const current=seasonAverages(player),currentRow=current.gp?`<tr class="current-season"><td>${seasonName(league.seasonYear).replace("–","-")}</td><td>Pro · Current</td><td>${player.age}</td><td>${current.gp}</td><td>${current.mpg}</td><td>${current.ppg}</td><td>${current.rpg}</td><td>${current.apg}</td><td>${current.fg}</td><td>${current.three}</td></tr>`:"";
  return `<div class="history"><p class="eyebrow">BASKETBALL HISTORY</p><div class="table-wrap"><table><thead><tr><th>Season</th><th>Level</th><th>Age</th><th>GP</th><th>MIN</th><th>PTS</th><th>REB</th><th>AST</th><th>FG%</th><th>3P%</th></tr></thead><tbody>${currentRow}${player.history.map(s=>`<tr><td>${s.season}</td><td>${s.level}${s.team?` · ${s.team}`:""}</td><td>${s.age}</td><td>${s.games}</td><td>${s.mpg}</td><td>${s.ppg}</td><td>${s.rpg}</td><td>${s.apg}</td><td>${s.fg}</td><td>${s.three}</td></tr>`).join("")}</tbody></table></div></div>${postseasonHistoryHtml(player)}`;
}

function postseasonHistoryHtml(player){
  const averages=postseasonAverages(player);if(!averages.gp)return "";
  const games=(league.postseason?.results||[]).map(game=>{const homeLine=game.homeBox?.find(x=>x.playerId===player.id),awayLine=game.awayBox?.find(x=>x.playerId===player.id),line=homeLine||awayLine;if(!line)return null;const teamId=homeLine?game.homeId:game.awayId,oppId=homeLine?game.awayId:game.homeId,ourScore=homeLine?game.homeScore:game.awayScore,oppScore=homeLine?game.awayScore:game.homeScore;return {game,line,oppId,won:ourScore>oppScore,ourScore,oppScore};}).filter(Boolean);
  const rows=games.map(({game,line,oppId,won,ourScore,oppScore})=>`<tr><td>${game.stage}</td><td>G${game.seriesGame}</td><td>${league.teams[oppId].name}</td><td><b class="${won?"win":"loss"}">${won?"W":"L"}</b> ${ourScore}–${oppScore}</td><td>${line.minutes}</td><td>${line.points}</td><td>${line.rebounds}</td><td>${line.assists}</td><td>${line.performance}</td></tr>`).join("");
  return `<div class="history postseason-history"><p class="eyebrow">${league.seasonYear+1} PLAYOFFS</p><div class="playoff-summary"><strong>${averages.gp} games</strong><span>${averages.ppg} PPG · ${averages.rpg} RPG · ${averages.apg} APG</span></div>${rows?`<div class="table-wrap"><table><thead><tr><th>Round</th><th>Game</th><th>Opponent</th><th>Result</th><th>MIN</th><th>PTS</th><th>REB</th><th>AST</th><th>Rating</th></tr></thead><tbody>${rows}</tbody></table></div>`:`<p class="summary">Playoff totals were preserved, but this compact save does not include each individual game log.</p>`}</div>`;
}

function contractMoney(amount){return `$${Number(amount||0).toFixed(3)}M`;}

function contractHtml(player){
  if(player.teamId===null||!player.contract?.salaries?.length)return "";
  const contract=player.contract,futureStart=contract.salaries[0].seasonYear>(league.seasonYear||2026),guaranteedValue=contract.salaries.filter(row=>row.guaranteed).reduce((sum,row)=>sum+row.amount,0),hasOption=contract.salaries.some(row=>row.option&&!row.option.includes("exercised")),guaranteeLabel=hasOption?`${contractMoney(guaranteedValue)} currently guaranteed`:"Fully guaranteed",rows=contract.salaries.map((row,index)=>{const option=row.option||"—",security=row.guaranteed?"Guaranteed":row.option?"Not guaranteed until exercised":"Non-guaranteed",yearLabel=futureStart&&index===0?" · Begins":!futureStart&&row.seasonYear===(league.seasonYear||2026)?" · Current":"";return `<tr class="${yearLabel?"current-contract-year":""}"><td>${row.seasonYear}–${String(row.seasonYear+1).slice(-2)}${yearLabel}</td><td><strong>${contractMoney(row.amount)}</strong></td><td>${escapeHtml(security)}</td><td>${escapeHtml(option)}</td></tr>`;}).join("");
  return `<section class="contract-card"><div class="contract-card-heading"><div><p class="eyebrow">CONTRACT DETAILS</p><h3>${escapeHtml(contract.type)}</h3></div><span class="contract-type-badge">${escapeHtml(contract.type.replace(" Contract",""))}</span></div><div class="contract-overview"><div><small>${futureStart?"First-year cap hit":"Current cap hit"}</small><strong>${contractMoney(contract.salary)}</strong></div><div><small>${hasOption?"Potential":"Total"} remaining value</small><strong>${contractMoney(contract.totalValue)}</strong></div><div><small>Guaranteed value</small><strong>${contractMoney(guaranteedValue)}</strong></div><div><small>Term remaining</small><strong>${contract.years} year${contract.years===1?"":"s"}</strong></div><div><small>Free agency</small><strong>${contract.freeAgencyYear} · ${escapeHtml(contract.freeAgencyType)}</strong></div></div><div class="contract-terms"><span>${escapeHtml(guaranteeLabel)}</span><span>Signed using: ${escapeHtml(contract.signedUsing||"Cap Space")}</span><span>${contract.raisePercent||0}% annual raises</span><span>Original term: ${contract.originalLength||contract.years} years</span></div><div class="table-wrap contract-table"><table><thead><tr><th>Season</th><th>Salary / cap hit</th><th>Guarantee</th><th>Option</th></tr></thead><tbody>${rows}</tbody></table></div><p class="contract-note">Contract terms and salaries are public information. Team options, player options and guarantees will affect future offseason decisions.</p></section>`;
}

function openPlayer(playerId,viewerId,returnToBoxScore=null){
  const p=league.players.find(x=>x.id===playerId)||league.prospects.find(x=>x.id===playerId),r=scoutingReport(league,viewerId,p),viewer=league.teams[viewerId],why=playerScoutExplanation(r,p,viewer),teamName=p.teamId===null?(r.isProspect?p.college:"Free agent"):league.teams[p.teamId].name,perf=performanceSummary(p),condition=playerCondition(p),overallDisplay=r.own?`${r.perceived} OVR`:`Estimated OVR ${r.overallLow}–${r.overallHigh}`,development=p.age<=25?`Projected peak ${r.estimates.potential.low}–${r.estimates.potential.high}`:p.age<=29?`Current ceiling ${r.estimates.potential.low}–${r.estimates.potential.high}`:`Career peak ${perf.careerPeak} · ${perf.trajectory}`,form=perf.currentForm===null?"No current-season games":`Playing like ${perf.currentForm} over the last ${Math.min(10,p.season.gp)} games`,seasonImpact=perf.seasonImpact===null?"Not established":`Playing like ${perf.seasonImpact} across the season`,awardBadges=(p.awards||[]).map(award=>`<span>${award.seasonYear} ${escapeHtml(award.name)}</span>`).join("");
  $("dialog-content").innerHTML=`<p class="eyebrow">${r.isProspect?"DRAFT SCOUTING REPORT":r.own?"INTERNAL PLAYER CARD":"PRO SCOUTING REPORT"}</p><div class="player-heading"><div class="avatar">${p.name.split(" ").map(x=>x[0]).join("")}</div><div><h2>${p.name}${heat(p,r)}</h2><p class="dialog-meta">Age ${p.age} · ${p.position}/${p.secondary} · ${inches(p.height)} · ${teamName}</p><p class="dialog-meta">${r.isProspect?`${league.seasonYear+1} prospect · Projected pick No. ${p.draftPick}`:p.freeAgency?.status==="Available"?`${p.experience} years pro · ${p.freeAgency.restricted?"Restricted":"Unrestricted"} free agent`:p.experience===0?`Rookie · Pick No. ${p.draftPick} · ${p.college}`:`${p.experience} years pro`} · ${r.marketTier}</p></div></div><div class="form-grid"><div><span>Current talent</span><strong>${overallDisplay} (${grade(r.perceived)})</strong></div><div><span>Current form</span><strong>${r.isProspect?"College production shown below":form}</strong></div><div><span>Season impact</span><strong>${r.isProspect?"Not yet an NBA player":seasonImpact}</strong></div><div><span>Development outlook</span><strong>${development}</strong></div><div><span>Health & conditioning</span><strong>${escapeHtml(condition.label)} · ${escapeHtml(condition.detail)}</strong></div></div>${awardBadges?`<div class="player-awards">${awardBadges}</div>`:""}${contractHtml(p)}<div class="scout-reasons"><div><strong>Projected role</strong><span>${why.projection}</span></div><div><strong>Attribute case</strong><span>Best traits: ${why.strengths.join(", ")}. Concerns: ${why.concerns.join(", ")}.</span></div><div><strong>Production evidence</strong><span>${why.evidence}</span></div><div><strong>Scouting context</strong><span>${why.staffNote}</span></div></div><div class="ratings dialog-ratings">${ATTRIBUTES.map(([key,label])=>{const e=r.estimates[key],displayLabel=key==="potential"?(p.age<=25?"Projected Peak":p.age<=29?"Current Ceiling":"Peak Estimate"):label;return `<div class="rating"><span>${displayLabel}</span><strong>${e.low}–${e.high}${commissioner?` <em class="true">(${e.true})</em>`:""}</strong></div>`}).join("")}</div>${historyHtml(p)}`;
  setDialogBack(returnToBoxScore);
  if(!$("player-dialog").open)$("player-dialog").showModal();
}

function switchScreen(screen){activeScreen=screen;document.querySelectorAll(".app-screen").forEach(x=>x.classList.toggle("hidden",x.id!==screen));document.querySelectorAll(".nav-tab").forEach(x=>x.classList.toggle("active",x.dataset.screen===screen));document.querySelectorAll(".trade-control").forEach(x=>x.classList.toggle("hidden",screen!=="trade-screen"));document.querySelector(".controls").classList.toggle("non-trade",screen!=="trade-screen");}

function startMode(spectator){
  if(allSaves().length>=MAX_SAVE_SLOTS){showToast(`All ${MAX_SAVE_SLOTS} save slots are full. Delete a league before starting another.`,"error");return;}
  const selectedTeamId=Number($("setup-team").value),newLeagueName=$("league-name").value.trim()||"Basketball Universe";
  pendingLeagueStart={spectator,selectedTeamId,newLeagueName};document.querySelector('input[name="financial-rule-preset"][value="modern"]').checked=true;document.querySelector('input[name="draft-class-strength"][value="realistic"]').checked=true;syncRulePresetCards();$("rules-league-summary").textContent=`${newLeagueName} · ${spectator?"Spectator":league.teams[selectedTeamId]?.name||"Selected team"}`;$("setup-screen").classList.add("closed");$("rules-screen").classList.remove("closed");
}
function selectedFinancialPreset(){return document.querySelector('input[name="financial-rule-preset"]:checked')?.value==="simplified"?"simplified":"modern";}
function selectedDraftClassStrength(){const selected=document.querySelector('input[name="draft-class-strength"]:checked')?.value;return DRAFT_CLASS_PRESETS[selected]?selected:"realistic";}
function syncRulePresetCards(){const selected=selectedFinancialPreset(),classStrength=selectedDraftClassStrength();document.querySelectorAll(".rule-preset-card,.draft-class-card").forEach(card=>card.classList.toggle("selected",card.querySelector("input").checked));$("confirm-rules").textContent=`Start league · ${selected==="simplified"?"Simplified cap":"Modern NBA"} · ${DRAFT_CLASS_PRESETS[classStrength].name} draft class`;}
function confirmLeagueRules(){
  if(!pendingLeagueStart)return;const {spectator,selectedTeamId,newLeagueName}=pendingLeagueStart,preset=selectedFinancialPreset(),draftClassStrength=selectedDraftClassStrength();
  league=createLeague(BASE_LEAGUE_SEED,null,{financialRulesPreset:preset,draftClassStrength});saveId=null;leagueName=newLeagueName;controlledTeamId=spectator?null:selectedTeamId;pendingLeagueStart=null;freeAgentFilters={...DEFAULT_FREE_AGENT_FILTERS};unsignedPlayerFilters={...DEFAULT_UNSIGNED_FILTERS};freeAgencyView="unsigned";resetTradeOffer();mountLeague();$("setup-team").value=selectedTeamId;$("viewer-team").value=selectedTeamId;applyModeUi();$("rules-screen").classList.add("closed");document.body.classList.remove("menu-open");populateOpponentTeams();populateScoutingTeams();render();const saved=saveLeague();showToast(saved?`✓ League created · ${financialRulePreset(league).name} · ${draftClassPreset(league).name} draft class`:"League opened, but browser storage could not save it.",saved?"success":"error");setTimeout(maybePromptScouting,0);
}
function cancelRuleSetup(){pendingLeagueStart=null;$("rules-screen").classList.add("closed");$("setup-screen").classList.remove("closed");}

